"""Datos leídos del Chuletario de Urgencias (www.chuletariodeurgencias.es, C. M. Prados Arredondo, CC BY-NC-SA 4.0)
para la plantilla v4 del Vademécum (mk_template4.py). Pautas parenterales, sueros, observaciones y contraindicaciones.
Las notas marcadas «(no es del Chuletario)» vienen de ficha técnica / guías."""
def P(ind, pres, via, dosis, freq='', dur='', mx=''):
    r = {"indicacion": ind, "presentacion": pres, "via": via, "dosis": dosis}
    if freq: r["frecuencia"] = freq
    if dur: r["duracion"] = dur
    if mx: r["maxima"] = mx
    return r

